metrics.workdir_dsl:
workspace "Parcel Tracker" "A parcel delivery tracking platform" {

    !impliedRelationships false

    configuration {
        scope softwareSystem
    }

    model {

        customer = person "Customer" "A customer who uses the platform to look up the status of their parcels"

        parcelTracker = softwareSystem "Parcel Tracker" "A parcel delivery tracking platform owned and operated by our company" {

            webPortal = container "Web Portal" "A web portal where customers look up shipments" "Web Application"
            dispatchService = container "Dispatch Service" "A service that assigns parcels to couriers" "Service"
            database = container "Database" "Stores shipments and dispatch records" "Database" "Database"
            pricingLibrary = container "Pricing Rules Library" "Computes delivery prices from weight and zone" "Library" "Library"
        }

        emailProvider = softwareSystem "Email Delivery Provider" "An email delivery provider operated by a different organization" "External"

        customer -> webPortal "looks up the status of their parcels" "HTTPS"
        customer -> parcelTracker "looks up the status of their parcels" "HTTPS"
        webPortal -> pricingLibrary "embeds" "Embedded"
        dispatchService -> pricingLibrary "embeds" "Embedded"
        dispatchService -> emailProvider "sends customer notification emails through" "SMTP"
        parcelTracker -> emailProvider "sends customer notification emails through" "SMTP"
        webPortal -> database "reads shipments from" "SQL"
        dispatchService -> database "writes dispatch records to" "SQL"
    }

    views {
        systemContext parcelTracker "SystemContext" {
            include *
            autoLayout
            title "System Context diagram for Parcel Tracker"
        }

        container parcelTracker "Containers" {
            include *
            autoLayout
            title "Container diagram for Parcel Tracker"
        }

        styles {
            element "Person" {
                shape Person
                background #08427B
                color #ffffff
            }
            element "Software System" {
                background #1168BD
                color #ffffff
            }
            element "External" {
                background #999999
                color #ffffff
            }
            element "Container" {
                background #438DD5
                color #ffffff
            }
            element "Database" {
                shape Cylinder
            }
            element "Library" {
                shape Hexagon
            }
        }
    }
}
